function v54ApplyBuiltinTheme() {
  try {
    if (!V54_BUILTIN_THEME) return false;
    // 單檔模式：內建主題一律套用（localStorage 殘留的路徑型主題無法在單檔中解析）
    return applyThemePack(V54_BUILTIN_THEME);
  } catch (_) { return false; }
}

/* 供 Codex 讀取的清單（語意圖示名＋槽位＋品牌）——製作規格由 THEME_ICONS/THEME_SLOTS 自動衍生 */
function themeManifest() {
  var out = { version: THEME.version, brand: BRAND, icons: Object.keys(THEME_ICONS), slots: {}, portraitSpec: PORTRAIT_SPEC };
  for (var k in THEME_SLOTS) if (Object.prototype.hasOwnProperty.call(THEME_SLOTS, k)) out.slots[k] = { css: THEME_SLOTS[k].css, kind: THEME_SLOTS[k].kind, desc: THEME_SLOTS[k].desc };
  return out;
}

/* v53 階段 3：單檔模式立即套用內建主題（同步，不等 async init，確保最早生效）
   模組版 V54_BUILTIN_THEME=null 跳過；單檔版此處已被建置工具填入 base64 化主題 */
try {
  if (V54_BUILTIN_THEME) {
    var _v54r = applyThemePack(V54_BUILTIN_THEME);
    if (typeof console !== "undefined") console.log("[v54 內建主題] 同步套用：" + (_v54r ? "成功" : "失敗"));
  }
} catch (_v54e) {
  if (typeof console !== "undefined") console.error("[v54 內建主題] 套用錯誤：", _v54e);
}

